// V2: Phân loại email theo categories
const emails = $input.all();
const VIP_SENDERS = [
  'boss@company.com', 'manager@company.com', 'ceo@company.com'
];
const SPAM_DOMAINS = [
  'shopee.vn', 'lazada.vn', 'tiki.vn', 'grab.com', 'newsletters.',
  'noreply@', 'no-reply@', 'donotreply@'
];
const PROMO_KEYWORDS = [
  'giảm giá', 'flash sale', 'khuyến mãi', 'ưu đãi', 'sale', 'discount',
  '% off', 'free', 'miễn phí', 'deal', 'voucher', 'coupon'
];
const NEWSLETTER_KEYWORDS = [
  'unsubscribe', 'newsletter', 'digest', 'weekly', 'monthly', 'bản tin',
  'no-reply', 'noreply'
];
const URGENT_KEYWORDS = [
  'urgent', 'khẩn', 'gấp', 'asap', 'deadline', 'hạn chót', 'cảnh báo',
  'warning', 'payment due', 'overdue', 'quá hạn', 'cần phản hồi'
];

const categories = { important: [], normal: [], newsletter: [], promotion: [], spam: [] };

emails.forEach(item => {
  const e = item.json;
  const from = (e.from || '').toLowerCase();
  const subject = (e.subject || '').toLowerCase();
  const body = (e.textPlain || e.snippet || '').toLowerCase();
  const full = `${from} ${subject} ${body}`;

  const isVIP = VIP_SENDERS.some(s => from.includes(s.toLowerCase()));
  const isSpamDomain = SPAM_DOMAINS.some(d => from.includes(d));
  const isPromo = PROMO_KEYWORDS.some(kw => full.includes(kw));
  const isNewsletter = NEWSLETTER_KEYWORDS.some(kw => full.includes(kw));
  const isUrgent = URGENT_KEYWORDS.some(kw => full.includes(kw));

  const fromClean = (e.from || '').replace(/<[^>]+>/g, '').trim();
  const info = { id: e.id, from: fromClean, subject: e.subject || '(no subject)' };

  if (isVIP || isUrgent) categories.important.push(info);
  else if (isSpamDomain && !isUrgent) categories.spam.push(info);
  else if (isPromo) categories.promotion.push(info);
  else if (isNewsletter) categories.newsletter.push(info);
  else categories.normal.push(info);
});

return [{ json: { categories, total: emails.length } }];

const { categories, total } = $input.first().json;

const dateStr = new Date().toLocaleDateString('vi-VN', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric',
  timeZone: 'Asia/Ho_Chi_Minh'
});

const fmt = (arr, max = 5) => arr.length === 0 ? '_Không có_' :
  arr.slice(0, max).map((e, i) => `  ${i+1}. *${(e.subject||'').substring(0,50)}*\n     📤 ${(e.from||'').substring(0,40)}`).join('\n') +
  (arr.length > max ? `\n  _... và ${arr.length - max} email khác_` : '');

const spamIds = categories.spam.map(e => e.id).filter(Boolean);

const message = `📧 *BÁO CÁO EMAIL SÁNG NAY*
📅 ${dateStr}

📊 *Thống kê:*
• ⭐ Quan trọng: ${categories.important.length}
• 📥 Bình thường: ${categories.normal.length}
• 📰 Newsletter: ${categories.newsletter.length}
• 🏷️ Khuyến mãi: ${categories.promotion.length}
• 🗑️ Spam/Quảng cáo: ${categories.spam.length}
• 📨 Tổng cộng: *${total} email*

⭐ *QUAN TRỌNG - Cần xử lý:*
${fmt(categories.important)}

📥 *BÌNH THƯỜNG:*
${fmt(categories.normal)}

🔔 _Tự động dọn ${categories.spam.length} email spam sau_`;

return [{ json: { message, spamIds, stats: { total, ...Object.fromEntries(Object.entries(categories).map(([k,v]) => [k, v.length])) } } }];

// Archive từng email spam
const spamIds = $('📊 Tạo Báo Cáo Chi Tiết').first().json.spamIds || [];

if (spamIds.length === 0) {
  return [{ json: { archived: 0, message: 'Không có spam để xóa' } }];
}

// Trả về từng ID để Gmail node xử lý tuần tự
return spamIds.map(id => ({ json: { emailId: id } }));

const trashed = $input.all().length;
const stats = $('📊 Tạo Báo Cáo Chi Tiết').first().json.stats;

console.log(`✅ Workflow hoàn tất: ${JSON.stringify(stats)}`);
console.log(`🗑️ Đã xóa ${trashed} email spam`);

return [{ json: { status: 'completed', trashed, stats, finished_at: new Date().toISOString() } }];
